  "recovered_c": "uint64_t fn_19(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < len) {\n    return VERA_ERR;\n  }\n\n  for (size_t i = 0; i < len; i++) {\n    uint8_t b = (arg >> (i % 8 * 8)) & 0xFF;\n    if ((i * (i + 1) & 1) != 0 || DAT_00104010 != 0) {\n      b = (b ^ (i << 7)) * 0x6b + DAT_00104008;\n    }\n    out[i] = (b << (i % 8) | b >> (8 - i % 8)) ^ in[i] ^ i;\n  }\n\n  return len;\n}"
